    ],
    "lacunas": [
      "Sem o término novo, cuja determinação depende das precedências e requisitos de disponibilidade ausentes, não se estabelece magnitude nem direção da variação."
    ],
    "motivo": "A comparação parte do término base D10, mas os dados fornecidos não permitem determinar o término após o aviso.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 500000,
