        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "O orçamento de referência fixo é R$ 5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      }
    ],
    "lacunas": [
      "O aviso acrescenta R$ 200,00, mas o valor da extensão, se houver, depende de proposta sem valor ou teto definido; não se sabe também se haverá extensão."
    ],
    "motivo": "Há um custo adicional definido e um possível custo de extensão não quantificado, portanto o custo total novo não é exato.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_6ffaeeffa7",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [
      "A magnitude depende do custo de extensão, se houver, cujo valor não foi definido."
    ],
    "motivo": "O aviso acrescenta R$ 200,00 ao orçamento e determina que eventual preço de extensão seja não negativo; assim, o aumento é certo, mas sua magnitude exata não é conhecida.",
    "unidade": "BRL_centavo"
  }
}

